-- Chartes graphiques initiales des 37 clans (2026-10-11).
-- Rédigées à partir d'un échantillon de ~30 illustration_prompt par clan
-- (cartes Jouables ET brouillons), description de race exclue : la charte
-- décrit l'univers commun du clan, la race reste le sujet de l'image.
-- Idempotent : n'insère que pour les clans qui n'ont encore aucune charte.

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Sylvains', 'Charte d''origine', true, 'Vert émeraude et vert mousse, ivoire, bronze, argent, touches d''or ; brun du bois pâle, gris-vert de la brume ; noir et argent pour les plumages d''orage.', 'Lumière tamisée qui filtre à travers la canopée, aube dorée, clair de lune, lumière froide entre les fougères ; parfois lumière d''orage dramatique ou lumière céleste pour les scènes épiques.', 'Fantasy réaliste et monumentale, rendu cinématographique, illustration verticale 2:3 ; grande échelle, perspectives vertigineuses dès que les aigles géants apparaissent.', 'Forêt ancienne et sacrée, chênes monumentaux, Chêne-Monde aux racines colossales, cime des arbres et plateformes vivantes, sous-bois humides et brumeux, clairières, ruisseaux bordés de saules, ciel au-dessus de la canopée.', 'Cuir renforcé, armures de bois vivant et de bronze, boucles d''argent, arcs longs en bois pâle ornés de plumes blanches, lances, boucliers étroits en forme de feuille, capes vert sombre, robes ivoire et mousse, bâtons noueux.', 'Feuilles et vrilles gravées, plumes (couronnes de branches et de plumes dorées), racines géantes, archers invisibles fondus dans le feuillage, brume magique verte et argentée, aigles géants en piqué.', 'Pas de texte ni de cadre ; pas d''architecture de pierre ou de marbre (c''est le registre des Hauts-Elfes) ; pas de magie tape-à-l''œil, elle reste subtile ; pas de métal lourd ni de plates.', 'Les plans mêlent forêt et ciel : attaques coordonnées entre la canopée et le ciel, archers au sol pendant que les aigles plongent.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Sylvains');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Hauts-Elfes', 'Charte d''origine', true, 'Ivoire, argent, or pâle et bleu azur dominants ; turquoise, bleu nuit, pourpre impérial pour l''astral, blanc lumineux et rouge solaire pour le feu du phénix.', 'Lumière claire et solaire, rayon au zénith, lumière volumétrique, crépuscule ou nuit étoilée cinématographique ; énergie concentrée et maîtrisée.', 'Fantasy épique réaliste et mature, élégante, raffinée, voire érudite ; compositions majestueuses ou militaires, action lisible, anatomie naturelle ; vertical 2:3.', 'Cité de marbre blanc, remparts, terrasses et balcons dominant la mer, palais fortifiés aux grands escaliers, flèches cristallines, temples, observatoires, bibliothèques, cours intérieures à colonnades.', 'Armures ivoire et argent à filets d''or, capes azur ou turquoise, robes bleu nuit et ivoire, casques à crête solaire, longues lances, boucliers en forme de rayon solaire, arcs d''argent finement ciselés, astrolabes de bronze doré, bâtons astraux.', 'Soleil et disque solaire à sept rayons, étoiles, constellations runiques, magie astrale géométrique, runes d''argent, dômes de lumière turquoise et or, flèches d''énergie stellaire, phénix renaissant dans un bassin sacré.', 'Pas d''explosion excessive ni de tempête chaotique, la magie reste contrôlée ; pas de texte lisible, de cadre, d''interface ou de filigrane ; pas de sous-bois rustiques (c''est le registre des Sylvains).', 'L''élégance et la discipline priment : chaque magie doit sembler précise et parfaitement maîtrisée.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Hauts-Elfes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Forêt d''Émeraude', 'Charte d''origine', true, 'Vert émeraude et or, rayons dorés, accents turquoise et or végétal ; paillettes irisées, poussière dorée, touches de givre et de fleurs selon les saisons.', 'Lumière dorée qui traverse la canopée, feuillages et auras luminescents, papillons et motes lumineux ; parfois clair de lune espiègle ou brume crépusculaire.', 'Fantasy réaliste, élégante, somptueuse, voire mythique ; féerique et merveilleuse ; verticale 2:3.', 'Clairières d''émeraude, pierres moussues, racines anciennes, cours cérémonielles, palais de feuilles aux arches vivantes, trônes de fleurs et de branches, forêts changeantes.', 'Vêtements tissés de feuilles, armures de plantes dorées, lances fleuries, couronnes émeraude, flûtes de roseau, lyres vivantes, rubans lumineux, ramures ornées de fleurs.', 'Fleurs, ailes de papillon et de libellule, cycle des quatre saisons, chants et chœurs, vagues de fleurs et de lumière, visages de fées cachés dans les feuilles, balances florales.', 'Pas de texte ni de bordure ; pas de grimdark ni de violence crue ; pas de métal froid ni de technologie.', 'C''est une Cour : hiérarchie royale (souveraine, gardiens, courtisans inclinés) mêlée d''espièglerie féerique.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Forêt d''Émeraude');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Combe Verte', 'Charte d''origine', true, 'Verts de colline et de haie, beige avoine, brun, rouge baie, or chaud ; lumière dorée-verte, crépuscule bleu et fenêtres dorées.', 'Lumière chaude et dorée, lumière douce de sous-bois, crépuscule de lanternes ; dans les scènes de guerre, ciel d''orage traversé de lumière dorée.', 'Fantasy réaliste et picturale, de l''atmosphère bucolique à l''épopée, illustration verticale.', 'Vallée de collines habitées, petites maisons dans les buttes aux portes rondes et cheminées, vergers anciens, haies, chemins bordés de lanternes, campagne vallonnée, banquets communautaires.', 'Capes vertes brodées de feuilles, capes brunes, vêtements rustiques, cuir simple, boucliers de bois à clous de cuivre, frondes et ceintures de galets, arcs courts, épées courtes anciennes, paniers de pommes, de pain et d''herbes.', 'Arbres qui s''éveillent (yeux et visages dans l''écorce), racines lumineuses qui soulèvent la vallée, pommiers, aubépine en fleurs, remèdes d''herboriste, communauté protégée par ses arbres.', 'Pas de texte ni de cadre ; pas de cartoon ; pas de grandes forteresses ni de métal lourd ; garder une échelle domestique et chaleureuse.', 'Contraste d''échelle récurrent entre les petits habitants et les Hommes-Arbres gardiens ; les machines ennemies sont renversées par la nature.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Combe Verte');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Forge Ardente', 'Charte d''origine', true, 'Noir de roche et d''acier sombre, bronze, rouge et orange de la forge, braises ; runes dorées et flamme blanche pour le sacré.', 'Lueur de forge orange ou rouge sombre, éclairage latéral chaud, contre-jour des fourneaux, ombres profondes, étincelles, vapeur et poussière minérale.', 'Illustration de carte en fantasy réaliste, verticale, au poids et à la puissance assumés ; compositions défensives ou monumentales.', 'Galeries souterraines, tunnels fortifiés, passages étroits, ponts métalliques au-dessus des gouffres, ateliers aux murs couverts d''armes, fonderies et fourneaux monumentaux, portes runiques, sanctuaires, réserves de charbon.', 'Armures de plates sombres, acier damassé, cottes de mailles, boucliers hexagonaux et runiques, marteaux de guerre, haches courtes, arbalètes lourdes à carreaux runiques, pioches, lanternes de bronze, chaînes, wagonnets, enclumes.', 'Runes gravées et emblèmes de forge, enclume circulaire, cœurs et yeux de braise des golems, filons de minerai rougeoyant, formations serrées derrière des murs de boucliers.', 'Explicitement pas de steampunk ni de cartoon (ni engrenages, ni vapeur mécanique de gnome) ; pas de texte ni de cadre.', 'Les golems d''acier noir et de bronze s''accompagnent souvent de petits guerriers qui en donnent l''échelle.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Forge Ardente');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Guilde des Ingénieurs', 'Charte d''origine', true, 'Cuivre, laiton, bronze, cuir brun, ardoise ; contraste entre lumière turquoise froide (cristaux, énergie) et ambre chaud (lampes, vapeur) ; touches de bleu électrique et de vert émeraude (champignons).', 'Lueurs froides turquoise des cristaux opposées aux lampes et à la vapeur ambrées, étincelles, reflets métalliques chauds.', 'Fantasy peinte, détaillée, spectaculaire et héroïque, jamais cartoon ; anatomie naturelle, effets lisibles, une pointe d''humour permise ; verticale 2:3.', 'Cité souterraine verticale en ardoise, ateliers étagés, passerelles, ascenseurs, chaînes d''assemblage, laboratoires, stands de tir, tubes pneumatiques, rails suspendus, cavernes aux cristaux turquoise et champignons émeraude.', 'Lunettes de protection, monocles complexes, tabliers renforcés, vêtements asymétriques, ceintures d''outils, casques de cuivre ; engrenages, ressorts, pistons, bobines, leviers, cadrans sans chiffres, gyroscopes, hélices de laiton, conduits de cristal.', 'Automates et petits « Gadgets », cœurs de cristal turquoise, arcs électriques, traînées ambre et turquoise, machines géantes (mammouth mécanique, canonnières volantes), assemblage et transformation de machines.', 'Pas de cartoon, pas de technologie futuriste (elle reste artisanale, médiévale-fantasy) ; pas de texte, de chiffres, de schémas lisibles, de logo ni de filigrane.', 'Des machines légèrement instables (fuites de vapeur, étincelles) qui gardent un côté bricolé.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Guilde des Ingénieurs');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Clan des Mille Tunnels', 'Charte d''origine', true, 'Gris granit, bruns de cuir et de laine, laiton et bronze, cuivre, fer ; lueur chaude des lanternes, accents or et argent pour les trésors.', 'Lumière chaude et naturelle des lanternes de laiton, halos protecteurs doux dans l''obscurité des tunnels, atmosphère riche et coopérative.', 'Peinture numérique de haute fantasy réaliste, chaleureuse et bienveillante, parfois mystique ou épique.', 'Royaume souterrain : galeries de mine étayées, salles de logistique, points de contrôle aux portes de granit, chambres fortes aux portes runiques colossales, voûtes ancestrales, arches de granit monumentales, trésoreries circulaires, tunnels effondrés.', 'Vêtements de travail superposés en cuir et laine, manteaux de fourrure, bottes renforcées, gants, ceintures utilitaires ; lanternes, clés, sceaux et crochets de laiton, serrures de bronze, wagonnets, paniers de minerai, cartes et cordeaux.', 'Lanterne de laiton (emblème central, préférée à l''arme), clés et serrures, cartes de réseaux de tunnels, coffres scellés, reliques des générations, pierre primordiale, travail d''équipe.', 'Pas d''agressivité ni de monstruosité, le ton reste amical ; peu d''armes ; pas de lumière froide ni de magie flamboyante ; pas de griffes.', 'Clan de bâtisseurs, de gardiens et de logisticiens : on y montre le savoir-faire et la mémoire, pas la guerre.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Clan des Mille Tunnels');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Clan des Premiers Géants', 'Charte d''origine', true, 'Gris ardoise, ocre, vert lichen, ivoire, brun ; bronze patiné ; lueurs ambrées des inscriptions, blanc de la neige, orange des ciels de poussière.', 'Lumière froide d''aube ou de crépuscule en montagne, rayon de soleil perçant les nuages, soleil couchant derrière la poussière, faibles lueurs ambrées.', 'Peinture fantasy réaliste, solennelle, cinématographique, parfois apocalyptique ; échelle monumentale, compositions lourdes et crédibles ; vertical 2:3.', 'Haute montagne enneigée, cols brumeux, vallées, hauts plateaux, cercles de pierres, cairns mégalithiques et monolithes, amphithéâtres cyclopéens, ruines de forteresses, pins épars.', 'Bronze martelé et patiné (cuirasses, bracelets, anneaux de barbe), manteaux de laine sombre, laine ivoire et cuir brun, marteaux de pierre, haches à deux mains, burins de bronze, blocs et rochers.', 'Mégalithes, symboles géométriques gravés, runes simples qui luisent faiblement, ondes de choc qui fendent le sol, blocs lancés, mammouths laineux, petits humains ou soldats qui donnent l''échelle.', 'Pas de magie excessive ni d''effets magiques flamboyants ; pas de cartoon ; pas de texte, de cadre ni d''interface.', 'Le clan mêle géants, mammouths et humains qui guident, chantent ou balisent la route ; l''échelle se lit toujours par contraste avec des figures minuscules.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Clan des Premiers Géants');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Hordes des Steppes', 'Charte d''origine', true, 'Saturation maîtrisée : bleu nuit, rouge profond (ceintures), or vieilli discret, noir et argent, gris feutre, brun cuir, fourrure blanche et grise ; bleu-argent spectral, orange des feux contre un ciel anthracite froid.', 'Lumière cinématographique froide (hiver, ciel couvert, clair de lune, crépuscule), éclairages de rituel au brasero, feux de signal la nuit, profondeur atmosphérique.', 'Fantasy épique réaliste de jeu de cartes, peinture mate de concept art très détaillée, anatomie réaliste des humains, chevaux et loups, poses naturelles ; plein cadre vertical 2:3.', 'Steppe infinie balayée par le vent, prairies, crêtes rocheuses, lisière où la taïga sombre rencontre la steppe gelée, grands fleuves froids et gués, clairières enneigées, pins noirs.', 'Armures lamellaires, cottes de mailles, manteaux de feutre gris, cuir patiné, fourrures, arcs composites recourbés, haches courtes, boucliers, coiffes de bois de renne, plumes de corbeau, amulettes d''os, braseros de fer noir.', 'Étendards de crin noir, archers à cheval et cavaliers, troupeaux de chevaux de guerre, loups blancs spectraux de givre et de brume, empreintes de loup, lune pâle, chaînes de feux de signal, pactes et serments.', 'Pas de poses exagérées ni de couleurs sursaturées ; pas de sexualisation ; le surnaturel reste discret ; pas de texte.', 'Inspirations nomades d''Asie centrale (Kiptchaks, noyans) et de la frontière rus'' ; le surnaturel passe par l''esprit du loup et le chamanisme de la taïga.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Hordes des Steppes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'L''Empire de Jade', 'Charte d''origine', true, 'Jade profond, cinabre, noir d''encre, bronze patiné et ivoire ; touches de vert sombre sur les robes, d''argent sur les écailles et de gris sur les ciels.', 'Lumière cinématographique maîtrisée : soleil matinal sur les tuiles, visages à demi éclairés dans les archives, trouées de lumière nacrée ou de pluie dans les nuages pour le merveilleux.', 'Illustration de carte fantasy historique réaliste inspirée de la Chine impériale mythifiée, format vertical 2:3 plein cadre, sujet principal grand et lisible, matières détaillées, proportions naturelles, décor secondaire en retrait.', 'Pavillons et palais aux toits de tuiles, jardins et bassins, cours militaires poussiéreuses, tentes de campagne, archives impériales, fleuves embrumés avec jonques, montagnes en arrière-plan, brèches de remparts.', 'Armures lamellaires (noires ornées de bronze), robes de soie vert profond ou ivoire, manteaux rouges, bois laqué, rideaux de soie, coupes de bronze ; armes chinoises : hallebardes, dao, lances, arbalètes en rangs.', 'Sceaux de jade, éventails de commandement, rouleaux scellés et tablettes, cartes de campagne, bannières inclinées, voiles cinabre, fleurs de prunier, plumes de phénix lumineuses, dragons serpentiformes sans ailes, baguettes divinatoires.', 'Texte lisible, bordure, logo, esthétique cartoon, éléments modernes ; tout équipement de ninja ou de samouraï (pas de Japon) ; dragons ailés à l''occidentale.', 'Clan de l''État et de la stratégie : beaucoup de scènes administratives, d''ordres donnés, de rangs disciplinés et de reddition. Les humains ont des traits d''Asie de l''Est. Le merveilleux taoïste (immortels, phénix, dragons) reste lumineux et serein, jamais macabre.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'L''Empire de Jade');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Lames de l''Ombre', 'Charte d''origine', true, 'Indigo et noir laqué dominants, accents cinabre et acier froid, or vieilli sur les armures de haut rang, ivoire sur les manches, ciels bleu-gris.', 'Éclairage cinématographique : aube indigo, lune partiellement voilée de nuages, brume sur les champs de bataille, étincelles discrètes au choc des lames.', 'Illustration de carte fantasy historique réaliste du Japon féodal, format vertical 2:3 plein cadre, sujet net et lisible, anatomie crédible, matières détaillées ; cadrages serrés possibles sur les mains et les armes.', 'Forteresses japonaises et leurs galeries, cours de pierre humide, remparts brisés, portes de bois massives, marches de temple, résidences fortifiées, promontoires sur champ de bataille brumeux.', 'Armures laquées noires à cordons cinabre, kabuto au croissant argenté, tenues indigo renforcées d''acier noir pour les ombres, robes grises ; katana, naginata, yumi, lances, lames courtes ; bois sombre, cloches de bronze.', 'Bannières sombres, katana rengainé, croissant de casque, silhouettes de ninja derrière les piliers, oni en armure japonaise, archers sur les galeries, flèches aux trajectoires nettes.', 'Esthétique anime ou cartoon, texte, bordure, logo ; armes démesurées, halos excessifs, blessures graphiques ; magie spectaculaire non demandée.', 'Magie discrète uniquement si la carte la décrit. La sobriété et la dignité dominent : gestes calmes, compositions majestueuses, violence suggérée plutôt que montrée.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Lames de l''Ombre');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Défenseurs d''Ivoire', 'Charte d''origine', true, 'Grès chaud, bronze patiné, ivoire et vert jade ; blanc des lotus et reflets de l''eau.', 'Lumière tropicale : après-mousson, fin d''après-midi, pluie fine ; eaux lumineuses pour la magie de soin.', 'Illustration de carte fantasy réaliste d''inspiration khmère et Angkor, format vertical plein cadre, matières détaillées, silhouette centrale nette et sujet principal lisible.', 'Chaussées monumentales, terrasses et escaliers de grès, cités vivantes immenses, pavillons ouverts, bassins et réseaux d''eau, brèches inondées, rizières et paysages de mousson.', 'Armures de bronze, étoffes et tissus ivoire lourds, hautes coiffes sobres, bâtons de commandement, lances et boucliers, jarres de terre cuite, vasques rituelles, couvertures ivoire pour les éléphants.', 'Lotus (souvent seul emblème des bannières), bassins sacrés, éléphants d''Asie avec cornacs donnant l''échelle, feuilles médicinales et coupes d''eau, bannières ivoire.', 'Texte, bordure, logo, style cartoon ; armure européenne ; surcharge d''emblèmes (le lotus suffit).', 'Clan défensif et nourricier : nombreuses scènes de soin, de protection et d''eau. Prestance humaine réaliste, pas de surhumanité. Les éléphants ont une peau et des oreilles réalistes d''éléphant d''Asie.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Défenseurs d''Ivoire');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Enfants du Soleil', 'Charte d''origine', true, 'Or, obsidienne, jade, vert émeraude de la jungle, orange et rouge des flammes solaires, peintures de guerre cramoisies et dorées ; rouge sang pour les rituels nocturnes.', 'Éclairage dramatique : rayons de soleil perçant la canopée, couchers de soleil enfumés, torches et braseros, lueurs de runes, contre-jours (rim lighting), lune rouge pour les rituels.', 'Illustration fantasy ultra détaillée de jeu de cartes à collectionner AAA, style peint, composition dynamique et cinématographique, ton épique et mystique.', 'Pyramides et temples de jungle couverts de lianes et de mousse, autels de pierre runiques, statues anciennes, forêt tropicale dense, brume tropicale, ciels d''orage.', 'Armures tribales de cuir, bronze, plumes, jade et or ; plaques de pierre gravée ; lances et armes d''obsidienne, arcs cérémoniels, boucliers ornés ; robes cérémonielles à plumes.', 'Symboles et runes solaires, soleil, peintures de guerre, totems animaux spirituels, flèches enchantées, énergie magique dorée et émeraude, armes de feu et d''or en fusion.', 'Rendu gore (rituels intenses mais ni sanglants ni macabres), texte, bordure ; décors modernes.', 'Fusion assumée d''Amazones et d''Incas mythifiés ; référence visuelle : illustrations de Magic: The Gathering et Hearthstone.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Enfants du Soleil');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Seigneurs des Dunes', 'Charte d''origine', true, 'Bleu indigo riche, or du désert, cuivre, turquoise, grès, orange et cramoisi du couchant ; touches de safran et d''ivoire.', 'Lumière cinématographique : couchants flamboyants, soleil écrasant, torches dans les tombeaux, sable doré en suspension, tempêtes de sable qui voilent l''horizon.', 'Illustration fantasy épique de jeu de cartes, très détaillée, mouvement dramatique et poses d''action dynamiques, composition verticale de qualité « masterpiece ».', 'Dunes infinies, caravanes marchandes, ruines et arches de pierre érodées, nécropoles et tombeaux royaux, sarcophages et statues de rois oubliés, palais de grès, minarets, jardins d''oasis, cités caravanières, pavillons royaux.', 'Robes et voiles indigo superposés, tagelmust, soie brodée d''or, armure de bronze ou d''or sertie de turquoise, cuir, cimeterres ornés de pierres, couteaux de lancer, lances, montures du désert et chameaux.', 'Trésors et coffres débordant d''or, chaînes de pièces et médaillons, reliques et artefacts luisants, cartes commerciales, contrats et registres, étendards solaires, spirales de sable.', 'Texte et bordures ; visages entièrement découverts chez les guerriers nomades (le voile ne laisse voir que les yeux ambrés).', 'Univers de pillards, mercenaires et seigneurs marchands : la richesse et le contrôle des routes commerciales sont au cœur de chaque scène.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Seigneurs des Dunes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Le Royaume des Masques', 'Charte d''origine', true, 'Indigo, ocre, ivoire, turquoise, rouge corail, safran et écarlate ; bronze patiné et éclats dorés.', 'Lumière d''aube paisible ou ombres profondes de sanctuaire, lanternes, poussière dorée en suspension, lueurs corail ou turquoise lors des révélations divinatoires.', 'Illustration fantasy pour carte à collectionner, format vertical, tour à tour majestueuse, mystérieuse ou dynamique, atmosphère spirituelle et prophétique.', 'Sanctuaires yoruba fantastiques en bois sombre, arbres monumentaux aux racines enveloppantes, cours éclairées de lanternes, cités cérémonielles aux murs ocre et portes de bois sculpté, autels.', 'Couches de tissus indigo, turquoise, corail et safran, perles ivoire, colliers de perles et de coquillages, plaques de bronze patiné, cuir sombre, bois sculpté, lances à large lame, boucliers circulaires en bois.', 'Masques cérémoniels et masques de guerre (parfois surmontés d''oiseaux sculptés), cauris, plateaux divinatoires circulaires, rubans flottants, poudre ivoire, silhouettes d''ancêtres reliées par des fils, esprits faits de tissu.', 'Esthétique macabre et crânes, reproduction exacte de signes sacrés réels, personnages ou éléments européens ou égyptiens, costumes de danse orientale, texte, cadre.', 'Les esprits ancestraux sont formés de tissus et de masques, sans corps visible. Les signes divinatoires doivent être fictifs ; la représentation de la culture yoruba reste respectueuse.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Le Royaume des Masques');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Fils du Volcan', 'Charte d''origine', true, 'Noir du basalte, rouge et orange de la lave et des braises, rouge cramoisi des fleurs de lehua, vert des fougères et des écailles, ivoire du kapa ; bleu des vagues nocturnes.', 'Lumière volcanique dramatique (fissures rougeoyantes, roches qui pulsent), vapeur et étincelles, plages sous la lune, soleil qui perce la canopée pour les scènes de guérison.', 'Fantasy mythologique hawaïenne ou polynésienne réaliste, peinture numérique détaillée et cinématographique, illustration verticale.', 'Côtes et plages de basalte et de sable noir, rivières de lave, terres volcaniques refroidies, forêts d''ʻōhiʻa lehua, sources secrètes et cascades, volcan au loin, premières habitations de bois.', 'Kapa (étoffe d''écorce) aux motifs originaux, fibres tressées, bijoux de pierre volcanique, lances de bois, tambours de bois, torches, coupes de pierre ; jamais de métal.', 'Fleurs de lehua et pétales rouges lumineux, couronnes de fleurs, chants rituels en cercle, esprits sous forme de lumière rouge et verte, renaissance de la végétation sur la lave, gardiennes moʻo.', 'Armure métallique, clichés touristiques, dragons occidentaux, texte, cadre, bordure, logo.', 'Le chant est un vecteur central de la magie (protection, soin, renaissance). Design culturellement respectueux.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Fils du Volcan');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Le Royaume du Nord', 'Charte d''origine', true, 'Neige ivoire, bleu glacier, gris ardoise, vert sombre des pins, cuir brun, fer patiné, quelques accents rouge sombre.', 'Lumières froides de jour, crépuscule, lune pâle, ou teintes chaudes de feu de camp ; tempêtes et bourrasques utilisées avec mesure pour ne pas masquer les personnages.', 'Dessin fantasy peint, détaillé et expressif, vertical 2:3 plein cadre ; silhouette principale nette et lisible, arrière-plan plus doux ; jamais photoréaliste ni cartoon.', 'Forêts de pins enneigées, cols balayés par la neige, plaines gelées, plages de fjord et mer grise, ruisseaux gelés, palissades et camps retranchés, tertres.', 'Laine, fourrure, cuir et mailles crédibles, pauldrons doublés de fourrure, boucliers ronds en bois, haches, armes et équipements médiévaux nordiques, harnais de cuir pour les bêtes de guerre.', 'Meutes de loups et ours de guerre guidés par des dresseurs, runes gravées, givre sur les armes, bannières plaquées par le vent, pins miniatures pour donner l''échelle aux colosses.', 'Photoréalisme, photographie, cartoon, monstres caricaturaux, tempêtes qui noient le sujet, texte, cadre, logo, filigrane.', 'Fort lien entre humains et bêtes (loups, ours, yétis) : les animaux sont puissants mais crédibles, souvent protecteurs. Gestes calmes, sauvagerie maîtrisée.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Le Royaume du Nord');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'L''Ordre de l''Aube', 'Charte d''origine', true, 'Ivoire, lin écru, rouge sombre usé, acier, fer noirci et or terni ; ciels pâles ou rose pâle.', 'Éclairage d''aube sobre, lumière dorée douce, lumière de fenêtre dans les intérieurs de pierre, cendres en suspension.', 'Dessin fantasy peint et détaillé, vertical 2:3 plein cadre, illustré, expressif et lisible ; anatomie crédible, silhouette nette, arrière-plan moins détaillé que le sujet.', 'Cours de commanderie, chapelles (parfois calcinées), portes fortifiées, arches et ruelles de pierre, infirmeries de pierre, remparts au lever du jour.', 'Armures de plates marquées par l''usage, boucliers, manteaux clairs ou rouge sombre noués à l''épaule, tissus rapiécés, robes de laine ivoire, tabliers bruns, lances, lampes, parchemins scellés.', 'Croix rouge fanée sur fond ivoire, bannières usées, couronne solaire, gestes de protection (bouclier levé devant un blessé), main sur l''épaule, fraternité d''armes, soins.', 'Photoréalisme, photographie, cartoon, texte, cadre, logo, filigrane ; effets magiques tape-à-l''œil (on montre le geste protecteur plutôt que la magie) ; armures rutilantes.', 'Ordre humble et usé plutôt que glorieux : équipement patiné, tissus rapiécés, solidarité. Éviter le bleu royal et l''or éclatant.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'L''Ordre de l''Aube');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Sublime Porte', 'Charte d''origine', true, 'Grenat, émeraude, ivoire et bleu nuit, rehaussés d''orange (feu, braseros, couchant) et de fumée anthracite ; touches d''or et de bronze (armures lamellaires dorées, étriers, tulipes dorées).', 'Lumière orange chaude, celle du couchant, du matin ou des braseros, contre des ombres et des ciels bleu nuit ; éclairs orange des salves pris dans la fumée anthracite ; lumière latérale pour les portraits.', 'Réalisme historique, inspiré de l''Empire ottoman préindustriel (XVe-XVIIe siècle), sobre et crédible. Visages variés et individualisés (Turcs, Balkaniques, Arméniens, Kurdes, Arabes, Géorgiens, Circassiens), formations disciplinées mais organiques, jamais uniformes.', 'Arsenaux et cours d''arsenal, remparts et créneaux de forteresse, portes monumentales, galeries de palais à mosaïques, coupoles de cuivre, routes impériales bordées de bornes, brèches fumantes dans des murailles, rues en pierre claire.', 'Caftans grenat ou émeraude, coiffe janissaire en feutre ivoire à retombée, şalvar, larges ceintures, armure lamellaire de bronze ou dorée, casque conique à nasal, turban. Mousquets à mèche, bombardes et canons de bronze, kilij, yatagan, arc composite, longue lance, pique, petit bouclier rond. Outils de cuivre, tabliers de cuir.', 'Emblème et bannière verte de la « Porte de Feu », tulipes gravées ou dorées (sur canons et créneaux), étoiles à huit branches, bois sculpté, bannières de campagne usées.', 'Armes et munitions modernes, fusils, baïonnettes, armes à percussion, uniformes napoléoniens, armures de plates et chevaliers occidentaux, montures fantastiques, monstres, magie spectaculaire, architecture gothique, armure sexualisée, mécanismes automatiques, texte ni cadre.', 'Univers presque sans magie : la puissance vient de la poudre, de l''artillerie et de l''organisation. Les inventions (canon à sept tubes) restent mécaniques et artisanales. Insister sur la diversité ethnique de l''Empire.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Sublime Porte');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Guerrières du Vent', 'Charte d''origine', true, 'Bronze patiné, ivoire et rouge garance dominants ; pierre claire, ciel d''or et de bleu. Variante des steppes : bleu tempête et anthracite.', 'Lumière méditerranéenne, limpide et solaire ; soleil levant, crépuscule doré, lumière sacrée dorée dans les sanctuaires, reflets sur les pointes de bronze.', 'Historique-fantasy réaliste, peinture cinématographique aux matières détaillées. Antiquité grecque et anatolienne (Amazones), parfois peuples cavaliers des hautes steppes. Composition verticale 2:3 plein cadre, sujet principal bien lisible.', 'Cités antiques et leurs terrasses, temples perchés, sanctuaires ouverts, portiques, portes monumentales, remparts, crêtes et gorges rocheuses, pavillons de campagne, terrain sec.', 'Cuirasses anatomiques et armures d''écailles en bronze, brassards, tuniques et capes ivoire ou garance, lin, ceintures rouges, bandes de cuir. Lances, javelots, arcs, sabres légèrement courbes, boucliers gravés, brasiers de bronze, vases de terre cuite, diadèmes sobres.', 'Soleil (boucliers gravés, lance solaire), pégases et griffons comme alliés, rubans garance sur les harnachements cérémoniels, lionnes, formations d''archères et de javelinières.', 'Éléments modernes ou médiévaux, style cartoon, sexualisation (anatomie athlétique crédible, protections fonctionnelles), gore et violence graphique, silhouettes spectrales, texte, logo ou bordure.', 'Toujours des femmes adultes aux traits méditerranéens et anatoliens variés. Les créatures (pégase, griffon) apparaissent souvent sans cavalier. Les adversaires restent flous, secondaires ou partiellement cadrés.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Guerrières du Vent');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Seigneurs Fauves', 'Charte d''origine', true, 'Orange safran, rouge impérial ou cramoisi, or et turquoise, avec de l''ivoire ; marbre blanc pour les variantes himalayennes.', 'Soleil doré éclatant, rais de lumière qui percent la canopée, piliers de lumière céleste, énergies spirituelles or, safran et turquoise ; éclairage dramatique et héroïque.', 'Fantasy épique de jeu de cartes, très détaillée et cinématographique, aux couleurs vibrantes ; inspiration indienne (maharajas du Rajasthan). Ton sacré et majestueux, poses héroïques et dynamiques.', 'Palais-temples du Rajasthan, ruines de temples envahies de lianes au cœur d''une jungle tropicale luxuriante, cours sacrées, bassins de lotus, jardins sacrés, terrasses enneigées face à l''Himalaya avec drapeaux de prière.', 'Armures cérémonielles ornées d''or et de filigrane, gemmes turquoise, soie rouge impériale, ivoire, colliers royaux dorés. Talwar courbe, chakrams de lancer, arc recourbé, dague de chasse courbe, sceptres, bannières.', 'Lotus (gravures, pétales qui dérivent, fleurs dorées), tigre rugissant et soleil (emblèmes, bannières, statues colossales de tigres), tigres et panthères spectraux, runes turquoise, les « neuf vies ».', 'Morts-vivants, gore, éléments modernes ; la destruction doit rester un jugement divin, sacré et non apocalyptique.', 'Fauves variés (tigre du Bengale, panthère noire, léopard des neiges) ; yeux turquoise ou dorés récurrents. Certaines cartes jouent le contraste « mignon mais dangereux ».'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Seigneurs Fauves');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Enfants de la Lune', 'Charte d''origine', true, 'Argent et bleu-blanc lunaire, noirs et gris de forêt, rouge sang (lune de sang, énergie cramoisie) ; yeux ambre, jaunes ou bleu pâle ; touches d''émeraude.', 'Pleine lune immense ou lune de sang, rayons de lune qui filtrent entre les branches tordues, brume et brouillard épais ; parfois une lueur orange de feu de camp. Ombres longues, dark fantasy cinématographique.', 'Dark fantasy cinématographique, menaçante et primale. Textures de fourrure détaillées, perspective atmosphérique, contre-plongées, poses de prédateur (traque, charge, hurlement).', 'Forêts anciennes et brumeuses aux pins tordus, falaises et éperons rocheux sous la lune, clairières, pierres levées, totems de pierre, ruines sacrées, pierres moussues, champs de bataille jonchés de compagnons tombés.', 'Lanières de cuir déchirées, ornements et trophées d''os, armures primitives de cuir et d''os incrustées d''argent, cuir clouté, griffes d''acier fixées aux gantelets.', 'Hurlement à la lune, loups spectraux qui jaillissent de la brume argentée, runes lunaires lumineuses sur la fourrure, traînées de sang luminescentes, malédiction primale, meute en formation de chasse.', 'Texte dans l''image ; ambiance lumineuse ou bucolique ; armures chevaleresques raffinées.', 'Thème du sacrifice et du deuil : la force des morts de la meute nourrit les survivants. Les ours-garous partagent le même univers lunaire et tribal.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Enfants de la Lune');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Le Pacte des Griffes', 'Charte d''origine', true, 'Grenat, la couleur signature du Pacte, avec bronze et or ; verts forestiers, ocre, ivoire ; turquoise et nacre pour les peuples d''eau.', 'Lumière dramatique ou héroïque : aube, soleil rasant, lune. Lueurs grenat qui relient les alliés, lumière verte et dorée dans les bosquets sacrés.', 'Fantasy réaliste et cinématographique, détaillée et épique ; scènes souvent collectives et multiraciales. Illustration verticale.', 'Le Cercle du Pacte, salles de conseil circulaires de pierre et de bois, bosquets ancestraux, cité arboricole, forêts, plaines, falaises, rivières, sanctuaires semi-immergés, camps nocturnes, ruines moussues, routes convergentes.', 'Armures de bronze (parfois oxydé), cuir noir, acier sombre, ornements de pierre sculptée, peaux cérémonielles, nacre. Capes et étoffes grenat, talismans et rubans. Grands boucliers circulaires, lances dentelées, tridents, marteaux de pierre, lames de bois vivant.', 'Emblème grenat du Pacte (à la ceinture, sur les capes et les bannières), les « dix marques » des dix peuples, cercles partagés, boucliers croisés, cartes gravées dans la pierre, délégations animales qui convergent.', 'Texte et bordure ; un peuple isolé sans signe d''alliance ; toute dissonance avec le grenat du Pacte.', 'Clan d''alliance entre dix peuples-bêtes (loups, ours, félins, chiens, renards, cerfs, singes, oiseaux, poissons, centaures). Toujours montrer la solidarité inter-races et le symbole grenat commun.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Le Pacte des Griffes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Harde Sauvage', 'Charte d''origine', true, 'Verts de forêt et de mousse, bruns, gris granit, bronze ; magie ancestrale émeraude et or ; touches de turquoise ; lueur orange des feux de camp, clairs de lune argentés.', 'Lumière de forêt primordiale, rais au-dessus des crêtes, clairières au clair de lune, feux de camp nocturnes, lueur spirituelle émeraude et dorée des ancêtres.', 'Peinture numérique de fantasy réaliste et cinématographique, très détaillée, format vertical 3:4. Ton noble et épique, parfois dark fantasy ; échelle monumentale pour les scènes de bataille.', 'Forêts primordiales, crêtes rocheuses moussues, chênes ancestraux, cercles de pierres levées, sources lumineuses, cols de montagne, vallées forestières, hautes herbes, avant-postes boisés.', 'Cuir patiné couvert de trophées, plaques de bronze gravées de motifs géométriques naturels, anneaux de bronze dans les cheveux tressés, talismans de bois sculpté, ornements en forme de bois de cerf, plumes. Grands arcs sculptés, lances (parfois gravées de runes), boucliers de bois, bâtons de racines, cors ancestraux.', 'Empreintes de sabots lumineuses, ancêtres spectraux, peintures de guerre tribales et rituelles, bannières de peau ornées de griffes, plumes, cornes et sabots, faucons dressés, troupeaux sacrés.', 'Cavaliers (jamais de cavalier, anatomie cohérente), texte, lettrage et cadre de carte.', 'Thèmes de la solidarité, de la vigilance et de la chasse légendaire ; volées coordonnées et charges disciplinées. Le clan rallie aussi d''autres peuples-bêtes.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Harde Sauvage');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Forêt Enchantée', 'Charte d''origine', true, 'Rose pastel, bleu ciel, lavande, vert menthe, crème chaude et or doux ; accents émeraude et ivoire pour la royauté.', 'Soleil chaud et lueur d''étoiles, lucioles, poussière d''étoiles et particules magiques flottantes, champignons lumineux ; éclairage cinématographique doux et lumineux.', 'Livre de contes fantaisiste, mignon et chaleureux, très détaillé et de qualité « masterpiece ». Grands yeux brillants, proportions chibi (tête et pattes surdimensionnées), humour bienveillant, ton joyeux.', 'Prairies enchantées sous le Grand Arbre au Gland Étoilé, clairières, fleurs géantes, champignons géants, souches, terriers douillets, salles du trône de branches fleuries.', 'Couronnes de fleurs, pendentifs en gland, rubans, petites capes d''aventurier, mini-armures de cuir, couronnes dorées étoilées, robes pastel brodées, trônes de racines lumineuses et de glands dorés, cristaux arc-en-ciel, lanternes.', 'Glands (dorés, lumineux, étoilés), étoiles, trèfles magiques, papillons, pétales flottants, lapins, écureuils, petits animaux mignons, gags visuels (petits accidents, chaos involontaire).', 'Ton sombre ou réaliste et violent, gore, couleurs saturées agressives, texte et bordures.', 'Royaume « mignon » (royaume Lumi) avec une reine humaine (Audrey, cheveux cuivrés, robe émeraude, ivoire et or). Les personnages ont souvent une personnalité comique : faux féroce, malchanceux, espiègle.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Forêt Enchantée');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Colère des Flammes', 'Charte d''origine', true, 'Orange, blanc-orange incandescent, jaune, cramoisi et or ; noir d''obsidienne, cendres grises et ciels sombres ; touches de cuivre.', 'Lumière émise par le sujet lui-même (magma, braises, flammes) dans des décors sombres ; sol fissuré qui rougeoie, halos solaires, brume de chaleur, contre-jour incandescent.', 'Fantasy réaliste et cinématographique, monumentale, parfois dark fantasy ; échelle mythique, mouvement vif, textures détaillées. Illustration verticale.', 'Mondes volcaniques, calderas, rivières de lave, cavités souterraines aux artères de lave, champs de bataille calcinés, horizons carbonisés, ciels noirs de cendres, sols d''obsidienne fissurés, pics d''obsidienne.', 'Magma, obsidienne, roche volcanique craquelée, plaques carbonisées qui s''effritent en braises, plumes incandescentes, plaques de cuivre et d''obsidienne fusionnées, lave liquide.', 'Phénix et halos solaires, œufs et nids de cendres, cercles runiques ou naturels incandescents, runes chauffées à blanc, braises portées par le vent, flammes rampantes comme des racines, cœurs de magma qui pulsent.', 'Texte et cadre ; tonalités froides ou décors verdoyants.', 'Créatures élémentaires faites de matière (flamme, magma, roche) plutôt que de silhouettes humanoïdes vêtues ; la puissance se lit dans la pression interne et les fissures lumineuses.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Colère des Flammes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Le Socle du Monde', 'Charte d''origine', true, 'Tons minéraux : ocre, argile rouge, grès, gris roche, noir magnétite, veines argentées ; éclats de cristal (vert malachite, quartz blanc et violet, turquoise) et prismes colorés.', 'Obscurité souterraine percée de lueurs minérales : lumière réfractée par les cristaux, rayons prismatiques, lumière ocre, cœurs lumineux ; poussière en suspension.', 'Fantasy géologique réaliste, épique et parfois sombre, aux textures détaillées ; échelle titanesque (plaques tectoniques, chaînes de montagnes). Illustration verticale.', 'Vastes cavernes veinées de minerai, galeries étroites, cathédrales de quartz, bassins souterrains, failles et gouffres abyssaux, géodes ouvertes, déserts rocheux au crépuscule, vallées et montagnes soulevées.', 'Roche, argile, grès, sable compacté, plaques minérales, malachite, quartz, magnétite, minerais métalliques ; pioches d''obsidienne, plaques de cuir et de roche.', 'Facettes géométriques naturelles, symboles géologiques scarifiés, lignes de force magnétiques, fragments en lévitation, cercles rituels autour de prismes flottants, fractures et failles, vagues de pierre.', 'Lave et feu (domaine d''un autre clan), esthétique féerique, science-fiction, machines et technologie industrielle, texte et cadre.', 'Le clan des profondeurs : la force vient de la terre elle-même (séismes, tectonique, magnétisme). Les troglodytes ont des visages pâles éclairés par les cristaux.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Le Socle du Monde');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Vague Sans Fin', 'Charte d''origine', true, 'Bleus profonds et bleu-noir des abysses, turquoise lumineux, blanc d''écume, reflets argentés. Bleu glacier et pâle pour les éléments de glace, perles noires et teintes sombres pour les scènes abyssales.', 'Bioluminescence dans l''obscurité des fosses, lueurs turquoise surnaturelles, clair de lune froid et brume marine. Éclairs argentés ou turquoise sur un ciel d''orage noir, aurores boréales sur les mers polaires.', 'Fantasy réaliste, cinématographique, épique ou majestueuse. Format vertical 2:3. Les corps d''eau sont translucides et montrent des courants internes. Les échelles sont monumentales : léviathans et vagues titanesques face à de minuscules silhouettes.', 'Fosses et failles sous-marines, palais et temples engloutis, observatoires et bibliothèques de corail et de verre, épaves englouties, rochers noyés de brume, ports et côtes sous la tempête, mers polaires, ruines couvertes de corail.', 'Corps et capes d''eau liquide, armures d''argent liquide, lames courbes faites de vagues. Corail, verre, cristal, coquillages noirs, diadèmes d''argent, robes couvertes de glyphes, rouleaux scellés dans des bulles ou sphères flottantes, chaînes anciennes brisées.', 'Vagues concentriques et murs d''eau, tourbillons et maelströms, spirales primordiales, cartes et routes de courants lumineux, souvenirs dans des bulles, anneaux sonores du chant des sirènes, perles lumineuses, runes bleu pâle dans l''eau.', 'Texte et cadre. Couleurs chaudes dominantes. Eau opaque ou plate. Style cartoon. Décors terrestres secs sans lien avec la mer.', 'L''échelle cosmique est fréquente : un océan infini contenu dans un corps, une mer et un ciel qui fusionnent.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Vague Sans Fin');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Le Souffle des Cimes', 'Charte d''origine', true, 'Blanc nuageux, azur, cyan et turquoise. Bleu pâle glacé, avec des pointes de violet dans les éclairs. Ciels d''un azur immaculé après la tempête.', 'Lumière froide d''altitude. Soleil perçant les nuées, rayons qui traversent un ciel fendu. Éclairs bleu-blanc et cyan crépitants, cœurs lumineux au centre des tourbillons.', 'Fantasy réaliste cinématographique, illustration verticale. Les silhouettes sont translucides, faites de vent, de brume et de nuages, et changent sans cesse de forme. Compositions dynamiques ou à la symétrie majestueuse.', 'Pics rocheux et crêtes enneigées, mers de nuages, montagnes flottantes, citadelles, temples et sanctuaires suspendus dans les nues, ponts célestes, cols entre deux sommets, œil d''un ouragan.', 'Air comprimé, courants entrelacés, nuages solidifiés, brume froide, cristaux de glace en suspension, couronnes d''air cristallin. Lames d''air et marteaux d''éclair cristallisé. Visages de marbre blanc qui se dissipent en brume.', 'Spirales et vortex, colonnes de vent, anneaux de nuages, courants contraires, rubans de brume, silhouettes préservées dans les nuées, œil lumineux au centre de l''ouragan, images prophétiques dans les nuages.', 'Texte et cadre. Teintes chaudes ou terreuses dominantes. Corps opaques et massifs. Décors souterrains ou de basse altitude. Style cartoon.', 'La puissance se dit par l''échelle météorologique : ouragans couvrant des horizons entiers, tempêtes traversant sept vallées. Les effets défensifs montrent des unités qui se dissipent en nuages.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Le Souffle des Cimes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Rangs Silencieux', 'Charte d''origine', true, 'Ivoire d''os, terre humide, brun sombre, gris cendre, vert-de-gris, métal noirci et rouillé. Teintes maladives mais désaturées, avec une vapeur gris-vert très discrète.', 'Lumière froide : crépuscule, aube grise, ciel couvert, lune derrière les nuages. Brume basse au sol. Pas de lueur magique vive.', 'Réalisme sombre, pictural, viscéral et cinématographique, en fantasy médiévale. Format vertical 2:3. Compositions militaires symétriques et panoramiques épiques montrant des légions infinies.', 'Cimetières fortifiés et boueux, fosses communes et charniers, cryptes et mausolées, caveaux ouverts, tertres funéraires et pierres levées renversées. Routes funéraires dans la brume, villages en quarantaine aux portes condamnées, cours de prison abandonnées, champs de bataille jonchés de lances brisées.', 'Armures funéraires rouillées ou rongées de vert-de-gris, grands boucliers rectangulaires, lances, hallebardes, épées à deux mains. Clous de fer, chaînes brisées, cercueils fendus, bijoux funéraires volés, vêtements paysans déchirés, étendards vides et déchirés.', 'Phalanges et murs de boucliers, morts surgissant de terre (mains, bras, tombes qui éclatent), discipline militaire inquiétante, os qui se remettent en place, banderoles sans insigne, statues décapitées, bougies éteintes, mouches et rats.', 'Magie flamboyante, auras surnaturelles brillantes, runes violettes, aura pourpre, spectres, fantômes, nécromanciens visibles. Texte, cadre. Visages grotesques ou caricaturaux.', 'C''est un clan de morts « physiques » : aucun élément spectral ni magique, la menace vient de la discipline et du nombre.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Rangs Silencieux');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Le Voile Hurlant', 'Charte d''origine', true, 'Cyan froid dominant, violet désaturé et violet sombre. Noir des rivières et des lacs, argent terni, blanc translucide des robes et des voiles.', 'Lueurs cyan de lanternes et de brume, lumière nocturne froide, pluie de nuit, ciels d''orage surnaturel. Lumière bleu-blanc émanant des orbites vides.', 'Dark fantasy réaliste, gothique et celtique, solennelle, mélancolique ou épique. Illustration de carte verticale. Corps et vêtements qui se dissolvent dans la brume.', 'Ponts anciens au-dessus de rivières noires, abbayes en ruine et cloîtres inondés, manoirs et couloirs gothiques hantés, cercles de pierres et menhirs, cimetières nocturnes, routes pavées et forêts mortes, forteresses englouties ou flottant dans la brume, villages endormis.', 'Robes et capuches translucides, armures médiévales corrodées, armures noires gravées d''argent, couronnes d''argent fêlées ou brisées, épées funéraires, longues lances noires, chaînes spectrales, lanternes cyan.', 'Processions d''âmes encapuchonnées, chaînes traînant sur la pierre, cris matérialisés en ondes et cercles lumineux, essaims d''âmes, têtes portées sous le bras, portails de brume, rivière séparant les mondes, corbeaux, portes qui claquent et meubles projetés.', 'Gore et texte. Couleurs chaudes. Corps de chair opaques. Zombies ou squelettes « physiques » (réservés aux Rangs Silencieux).', 'Le cri et le son sont rendus visibles par des ondes cyan. Une double veine gothique et celtique : banshees, dullahans, menhirs.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Le Voile Hurlant');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Cour Écarlate', 'Charte d''origine', true, 'Noir, bordeaux, écarlate et rubis, or vieilli et doré, ivoire des masques, argent lunaire, marbre noir, pierre gris-noir.', 'Clair de lune argenté, lune écarlate ou éclipse permanente, chandelles chaudes, lumière filtrée par des vitraux écarlates. Veines lumineuses rouges courant sur le marbre.', 'Dark fantasy réaliste et picturale, format vertical 2:3. Élégance inquiétante, majesté froide, opulence baroque et gothique.', 'Palais et cathédrales gothiques, salles du trône, bals nocturnes somptueux, cryptes aristocratiques, laboratoires alchimiques baroques avec cuves, casernes gothiques, tribunaux, cabinets luxueux, tours et toits dans la brume, forêts d''hiver avec un château au loin.', 'Armures noires finement gravées, capes bordeaux, vêtements brodés d''or, rapières rouge sombre, couronnes étroites, livrées écarlates, gants blancs. Tubes et instruments dorés, fioles de verre rouge, cœurs de rubis mécaniques, masques d''ivoire, registres reliés de cuir bordeaux, sceaux et blasons de maisons.', 'Couronne écarlate sur les bannières, filaments et brume de sang, cercles rituels dorés, cœurs de rubis, pétales de rose séchés, miroirs sans reflet, gargouilles qui s''animent, nuées de chiroptères, serviteurs humains en livrée.', 'Gore explicite, texte, cadre. Horreur crasseuse ou décor misérable : le clan reste aristocratique. Couleurs vives hors de la gamme rouge, noir et or.', 'Une société hiérarchisée : nobles vampires, officiers, serviteurs et soldats humains, créatures artificielles issues de l''hémomancie. Le sang est suggéré (une goutte, des filaments), jamais montré crûment.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Cour Écarlate');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Le Cénacle Nécromant', 'Charte d''origine', true, 'Bleu-vert (flammes, runes, poussière), noir, ivoire, or terni, cuivre noirci, bleu pétrole, violet noirci.', 'Lueurs bleu-vert des phylactères, des runes et des flammes logées dans la poitrine. Lumière subtile de nécropole et de bibliothèque souterraine.', 'Dark fantasy réaliste, épique ou cinématographique, format vertical 2:3. Le ton est savant et majestueux plutôt que putride. Anatomies « parfaitement » assemblées.', 'Bibliothèques circulaires ou infinies, laboratoires mortuaires avec cuves et passerelles, amphithéâtres d''étude, salles rituelles colossales, sanctuaires aux portes closes, couloirs de nécropole aux sarcophages alignés, salles d''archives.', 'Bandelettes sombres et sceaux de cire ivoire, armures cérémonielles d''or terni, robes et capes académiques noires, ivoire et or, couronnes d''ivoire. Scalpels d''ivoire, instruments de cuivre, masques de médecin funéraire, urnes funéraires, reliquaires, manuscrits et tablettes flottants.', 'Phylactères, noyaux et organes runiques lumineux, cercles chirurgicaux et funéraires, équations funéraires, bâton surmonté d''un œil fermé, scarabées noirs à glyphes de cuivre, sceaux brisés, nombres rituels (sept reliquaires, neuf cuves).', 'Style cartoon, texte, cadre. Chair putréfiée crue et gore. Dominante violette.', 'C''est une académie de la non-mort : maîtres, recteurs, disciples, archivistes. La nécromancie y est traitée comme une science et une érudition.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Le Cénacle Nécromant');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Cohortes Sanglantes', 'Charte d''origine', true, 'Peaux vertes, cuir brun usé, fer brut, os blanchis. Orange et rouge des flammes, ciels rouge sang ou couchants, fumée noire, yeux jaunes ou rouges.', 'Éclairage dramatique : couchants et crépuscules, incendies orangés projetant des ombres dures, éclairs d''orage, lumière rouge, clair de lune pâle, brume de l''aube.', 'Peinture numérique de fantasy épique et sombre, très détaillée, cinématographique, souvent en contre-plongée. Le ton est brutal et sauvage, avec une pointe d''humour malicieux pour les gobelins.', 'Champs de bataille boueux et brumeux, villages en flammes, cols et éperons rocheux, corniches enneigées, cavernes sombres, camps fortifiés de la Horde de Fer avec plateformes de commandement en bois, forêts brumeuses.', 'Armures de cuir en lambeaux, épaulières de fer, armures lourdes à pointes. Haches à double tranchant, cimeterres dentelés, lances grossières, dagues rouillées ou en os, boucliers ronds, trophées d''os et petits crânes, peintures de guerre tribales, explosifs artisanaux.', 'Chefs de guerre sur un éperon rocheux ralliant la troupe, charges de meutes, montures wargs, butin et pillage, entraînement et drills militaires, frères d''armes dos à dos, bâtons d''os des chamans, cicatrices.', 'Texte, éléments d''interface, cadre. Armures raffinées ou élégantes. Couleurs pastel. Décors urbains civilisés.', 'Deux facettes coexistent : la brutalité tribale et une « Horde de Fer » disciplinée et martiale (stratèges, instructeurs).'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Cohortes Sanglantes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'Les Princes des Abîmes', 'Charte d''origine', true, 'Cramoisi et noir dominants, obsidienne, lave et orange en fusion, yeux et fissures couleur braise. Touches de vert toxique et de violet corrompu.', 'Feu infernal et lueur de lave venue de l''intérieur des corps, fissures incandescentes, vortex d''énergie cramoisie, fumée noire, éclairage cinématographique dramatique.', 'Illustration de jeu de cartes en dark fantasy, verticale, très détaillée, épique et cataclysmique. Les petits diables peuvent être expressifs et humoristiques.', 'Royaume infernal, champs de bataille volcaniques, failles et portails déchirés dans le ciel, sols d''obsidienne fissurés gravés de sceaux, flèches d''obsidienne en feu, autels infernaux.', 'Peaux cramoisies, noires ou cendrées craquelées de lave, cornes recourbées d''obsidienne, griffes noires, ailes de chauve-souris membraneuses et déchirées. Armures d''obsidienne et de métal en fusion, robes rituelles cramoisies et noires, carapaces chitineuses.', 'Sceaux infernaux gravés, portails et failles, vortex de flammes, filaments de sang aspirés vers un démon invocateur, légions infernales, hiérarchie allant des larves et diablotins aux archidémons et seigneurs de guerre.', 'Texte et éléments d''interface. Lumière douce ou naturelle. Couleurs froides dominantes. Démons mignons, sauf pour les diablotins assumés comme comiques. Forêts elfiques (registre de La Forêt Maudite).', 'Une hiérarchie infernale visible d''une carte à l''autre : du diablotin comique à l''archidémon cataclysmique.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'Les Princes des Abîmes');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Forêt Maudite', 'Charte d''origine', true, 'Noir et violet profond, obsidienne, argent et filigrane d''argent. Vert émeraude toxique pour le poison. Accents cramoisis (yeux, capes), ambre parfois.', 'Pénombre et crépuscule, ombres vivantes, braseros violets, lueurs de runes pourpres, vapeurs vertes de venin, clair de lune dans les cours d''obsidienne.', 'Illustration de dark fantasy élégante et détaillée. Grâce aristocratique et menace silencieuse, ombres et images rémanentes pour la vitesse.', 'Citadelles et forteresses d''obsidienne, remparts, cavernes sous la citadelle, arbres d''obsidienne et ruines noires, cours au clair de lune, armureries et salles de guerre opulentes débordant d''or.', 'Armures de cuir noir ajustées ou de plates noires aux arêtes d''argent, robes et gowns noir et violet, bijoux, masques cérémoniels. Dagues et épées courbes d''obsidienne, arbalètes à répétition d''acier noir et de bois sombre, arcs recourbés, fioles d''argent ornées.', 'Araignées (veuves noires, motifs et emblèmes d''araignée argentés), venin, sigils de malédiction et vrilles d''ombre qui affaiblissent la cible, runes violettes, bannières de Maisons nobles, contrats de sang et marchandage, assassins synchronisés.', 'Texte, cadre. Couleurs vives et joyeuses. Forêt verdoyante ou lumineuse. Armures grossières ou tribales.', 'Malgré le nom du clan, l''univers est surtout celui d''une société matriarcale d''elfes noirs : citadelles d''obsidienne, intrigue, poison et commerce d''armes et de mercenaires. La « forêt » n''apparaît que par endroits (arbres d''obsidienne, lianes flétries).'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Forêt Maudite');

INSERT INTO public.style_guides (clan, name, is_default, palette, lighting, art_style, environments, materials, motifs, avoid, notes)
SELECT 'La Garde Noire', 'Charte d''origine', true, 'Métal noir, rouge incandescent et braises, bordeaux brûlé des capes et bannières, cendre grise, ciel rouge profond.', 'Éclipses totales cerclées de rouge, lueur rouge intérieure des armures et de leurs fissures, métal en fusion de la forge, braises montantes et cendres qui tombent, fumée épaisse.', 'Dark fantasy réaliste, épique et cinématographique, format vertical 2:3. Mouvements puissants mais réalistes, formations parfaitement alignées, détails précis du métal martelé.', 'Forges souterraines immenses et maudites, chapelles militaires en ruine aux vitraux brisés, champs de bataille sous l''éclipse, routes jonchées d''étendards abandonnés, forêts calcinées, remparts et portes de fer noir, tours volcaniques.', 'Armures noires vivantes, presque organiques, qui se referment sur le porteur. Chaînes monumentales, lances lourdes, épées et lames d''exécuteur, destriers caparaçonnés de métal, capes bordeaux, tabliers de cuir et cottes de mailles des forgerons.', 'Bannière bordeaux à la couronne brisée et à l''épée noire, runes et fissures rouges sur l''armure, chaînes qui se brisent, armures vides qui s''éveillent, éclipse, épée plantée dans la cendre, symboles gravés au fer rouge, charges de cavalerie.', 'Tentacules, mutations grotesques, squelettes ou zombies, créatures démoniaques excessives, technologie moderne, gore, texte, cadre.', 'Les soldats sont humains. Le surnaturel passe uniquement par l''armure maudite et l''éclipse, jamais par des monstres.'
WHERE NOT EXISTS (SELECT 1 FROM public.style_guides WHERE clan = 'La Garde Noire');
